55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const CURSE_SURCHARGE = 0.5;
60	
61	const HIGH_ENCHANTMENT_LEVEL = 5;
62	
63	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
64	
65	const LOYALTY_YEARS = 2;
66	
67	const LOYALTY_DISCOUNT = 0.2;
68	
69	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
70	
71	const BASE_PREMIUMS: Record<string, number> = {
72	  sword: 100,
73	  amulet: 60,
74	  staff: 80,
75	  potion: 40,
76	  rune: 25,
77	  moonstone: 25,
78	};
79	
80	const BLOCK_SIZE = 3;
81	
82	const BLOCK_BASE_PREMIUM = 60;
83	
84	const countsByType = (items: Item[]): Map<string, number> => {
85	  const counts = new Map<string, number>();
86	
87	  for (const item of items) {
88	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
89	  }
90	
91	  return counts;
92	};
93	
94	const typeBasePremium = (type: string, count: number): number =>
95	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
96	
97	const policyBasePremium = (items: Item[]): number =>
98	  [...countsByType(items)].reduce(
99	    (total, [type, count]) => total + typeBasePremium(type, count),
100	    0,
101	  );
102	
103	// Modifiers below all express a rate applied to some base. Keep every one of
104	// them in the form `base + base * RATE`. The algebraically equivalent
105	// `base * (1 + RATE)` is NOT safe here: 100 * 1.1 === 110.00000000000001 in
106	// IEEE-754, and Math.ceil turns that into 116 instead of 115. Ceil amplifies
107	// upward float error rather than absorbing it.
108	
109	// Item-specific modifiers: each is computed on the affected item's OWN base
110	// premium, then summed across items. Note this is the item's UNIT base premium
111	// — never the block-adjusted one. A rune inside a block of 3 is still
112	// surcharged on its own 25 G, not on its 20 G share of the block.
113	const unitBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
114	
115	const isHighlyEnchanted = (item: Item): boolean =>
116	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
117	
118	const itemSurchargeRate = (item: Item): number =>
119	  (item.cursed ? CURSE_SURCHARGE : 0) +
120	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
121	
122	const itemSurcharges = (items: Item[]): number =>
123	  items.reduce(
124	    (total, item) => total + unitBasePremium(item) * itemSurchargeRate(item),
125	    0,
126	  );
127	
128	// Policy-wide modifiers: each is computed on the policy base premium (the sum
129	// of all item base premiums), independent of which items make it up.
130	const isLoyal = (customer: Customer): boolean =>
131	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
132	
133	const policyModifierRate = (
134	  customer: Customer,
135	  previousQuotes: number,
136	): number =>
137	  FIRST_INSURANCE_SURCHARGE -
138	  (isLoyal(customer) ? LOYALTY_DISCOUNT : 0) -
139	  (previousQuotes > 0 ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
140	
141	const quote = (
142	  items: Item[],
143	  customer: Customer,
144	  previousQuotes: number,
145	): QuoteResult => {
146	  const policyBase = policyBasePremium(items);
147	  const policyModifiers =
148	    policyBase * policyModifierRate(customer, previousQuotes);
149	
150	  return {
151	    premium: Math.ceil(
152	      policyBase + itemSurcharges(items) + policyModifiers + PROCESSING_FEE,
153	    ),
154	  };
155	};
156	
157	export const runScenario = (scenario: Scenario): ScenarioResult => {
158	  const results: StepResult[] = [];
159	  let quotesSoFar = 0;
160	
161	  for (const step of scenario.steps) {
162	    if (step.op !== "quote") throw new Error(`Unsupported step: ${step.op}`);
163	
164	    results.push(quote(step.items, scenario.customer, quotesSoFar));
165	    quotesSoFar += 1;
166	  }
167	
168	  return { results };
169	};
